template.xpath:
/** 72mm override (hotel_pos_extension): paper-native 75% scale **/
#pos-receipt { width: 384px !important; font-size: 16.5px !important; }
#pos-receipt .text-small { font-size: 13.5px !important; line-height: 19.5px !important; }
#pos-receipt .text-normal { font-size: 16.5px !important; line-height: 23px !important; }
#pos-receipt .text-large { font-size: 22.5px !important; line-height: 30px !important; }
#pos-receipt .text-huge { font-size: 34px !important; line-height: 45px !important; }
#pos-receipt .text-insane { font-size: 37.5px !important; line-height: 55px !important; }
@page { size: 72mm auto; margin: 0; }
@media print { #pos-receipt { zoom: 1 !important; } }
